CREATE TABLE IF NOT EXISTS rules(
id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre varchar(200) NOT NULL,tipo_sensor varchar(50) NOT NULL,nivel varchar(20) NOT NULL CHECK(nivel IN ('VERDE','AMARILLO','NARANJA','ROJO')),
valor_minimo numeric(18,3),valor_maximo numeric(18,3),fenomeno varchar(50) NOT NULL,mensaje text NOT NULL,activo boolean NOT NULL DEFAULT true,
CHECK(valor_minimo IS NOT NULL OR valor_maximo IS NOT NULL),CHECK(valor_minimo IS NULL OR valor_maximo IS NULL OR valor_minimo<=valor_maximo));
CREATE TABLE IF NOT EXISTS alerts(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reading_id integer UNIQUE,sensor_id integer NOT NULL,comunidad_id integer NOT NULL,fecha_hora timestamptz NOT NULL,estado varchar(20) NOT NULL DEFAULT 'ACTIVA',activa boolean NOT NULL DEFAULT true,payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS alerts_community_date ON alerts(comunidad_id,fecha_hora);
CREATE TABLE IF NOT EXISTS events(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,alert_id integer REFERENCES alerts(id),sensor_id integer NOT NULL,comunidad_id integer NOT NULL,fecha_hora timestamptz NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS evaluation_receipts(reading_id integer PRIMARY KEY,alert_id integer REFERENCES alerts(id));
